{"caseId": "native-maintenance-allocation-python-2", "context": {"executionEngine": "python", "guide": "Return complete Python source defining decide(state). Inputs and outputs are the same JSON objects shown in the task and starter. Use only the Python standard library. Each call receives fresh copied input. Preserve all output fields and exact types; bool is distinct from integer. Decimal money is encoded as canonical strings without trailing zeros, using exact arithmetic rather than binary floats. For the allocation task only, reject invalid policy inputs by raising ValueError("policy_rejected"). Other exceptions are execution failures. Tests are optional; only independently checked request outcomes determine scores.", "outcomeContract": "Public expected outcomes wrap successful return values in result; rejected:true denotes a policy rejection. Do not add this wrapper to the function/request return value.", "publicProbes": [{"expected": {"result": {"allocation": {"shares": [{"amount": "0.01", "label": "first", "participates": true, "received_extra_cent": true, "remainder_score": "0.01"}, {"amount": "0", "label": "second", "participates": true, "received_extra_cent": false, "remainder_score": "0.01"}], "total": "0.01"}}}, "input": {"budget": {"recipients": [{"eligible": true, "label": "first", "weight": 0}, {"eligible": true, "label": "second", "weight": 0}], "total": "0.01"}}}, {"expected": {"result": {"allocation": {"shares": [{"amount": "0.01", "label": "first", "participates": true, "received_extra_cent": true, "remainder_score": "0.01"}, {"amount": "0", "label": "second", "participates": true, "received_extra_cent": false, "remainder_score": "0.01"}], "total": "0.01"}}}, "input": {"budget": {"recipients": [{"eligible": true, "label": "first", "weight": 1}, {"eligible": true, "label": "second", "weight": 1}], "total": "0.01"}}}], "request": "allocate budget", "source": "from fractions import Fraction


def cents_text(cents):
    whole, tail = divmod(cents, 100)
    return (f"{whole}.{tail:02d}".rstrip("0").rstrip(".") if tail else str(whole))


def decide(state):
    budget = state["budget"]
    total = Fraction(budget["total"])
    recipients = budget["recipients"]
    if total < 0 or (total * 100).denominator != 1:
        raise ValueError("policy_rejected")
    if any(row["weight"] < 0 for row in recipients):
        raise ValueError("policy_rejected")
    weights = [row["weight"] if row["eligible"] else 0 for row in recipients]
    eligible_weight = sum(weights)
    if total > 0 and eligible_weight == 0:
        raise ValueError("policy_rejected")
    total_cents = int(total * 100)
    shares = []
    allocated = 0
    for row, weight in zip(recipients, weights):
        amount = total_cents * weight // eligible_weight if eligible_weight else 0
        remainder = total_cents * weight - amount * eligible_weight
        allocated += amount
        shares.append({"label": row["label"], "participates": weight > 0,
                       "amount": amount, "remainder_score": remainder,
                       "received_extra_cent": False})
    while allocated < total_cents:
        winner = None
        for index, share in enumerate(shares):
            if share["participates"] and not share["received_extra_cent"]:
                if winner is None or share["remainder_score"] > shares[winner]["remainder_score"]:
                    winner = index
        assert winner is not None
        shares[winner]["amount"] += 1
        shares[winner]["received_extra_cent"] = True
        allocated += 1
    for share in shares:
        share["amount"] = cents_text(share["amount"])
        share["remainder_score"] = cents_text(share["remainder_score"])
    return {"allocation": {"shares": shares, "total": cents_text(total_cents)}}
